ACTIONS = {'register': 'register', 'import-materials-csv': 'import_materials_csv', 'update-material': 'update_material', 'move': 'movement', 'move-batch': 'movement_batch', 'preview-movements': 'preview_movements', 'import-movements-csv': 'import_movements_csv', 'stock': 'stock', 'history': 'history', 'movement-ledger': 'movement_ledger', 'count': 'count', 'count-batch': 'count_batch', 'preview-counts': 'preview_counts', 'confirm-counts': 'confirm_counts', 'confirm-location-counts': 'confirm_location_counts', 'import-counts-csv': 'import_counts_csv', 'counts': 'counts', 'reverse': 'reverse', 'reverse-batch': 'reverse_batch', 'preview-reversals': 'preview_reversals', 'reversals': 'reversals', 'set-minimum': 'set_minimum', 'shortages': 'shortages', 'replenishment-plan': 'replenishment_plan', 'inventory': 'inventory', 'stock-summary': 'stock_summary', 'export-inventory-csv': 'export_inventory_csv', 'set-active': 'set_active', 'material-status': 'material_status', 'material-changes': 'material_changes', 'create-purchase': 'create_purchase', 'create-replenishment-purchase': 'create_replenishment_purchase', 'import-purchases-csv': 'import_purchases_csv', 'purchase-order': 'purchase_order', 'purchase-changes': 'purchase_changes', 'cancel-purchase': 'cancel_purchase', 'reopen-purchases': 'reopen_purchases', 'update-purchase': 'update_purchase', 'adjust-purchase-quantities': 'adjust_purchase_quantities', 'receive-purchase': 'receive_purchase', 'receive-purchase-batch': 'receive_purchase_batch', 'import-purchase-receipts-csv': 'import_purchase_receipts_csv', 'preview-purchase-receipts': 'preview_purchase_receipts', 'purchase-receipts': 'purchase_receipts', 'return-purchase': 'return_purchase', 'return-purchase-batch': 'return_purchase_batch', 'import-purchase-returns-csv': 'import_purchase_returns_csv', 'preview-purchase-returns': 'preview_purchase_returns', 'purchase-returns': 'purchase_returns', 'purchase-progress': 'purchase_progress', 'purchase-orders': 'purchase_orders', 'export-purchases-csv': 'export_purchases_csv', 'save-supplier': 'save_supplier', 'import-suppliers-csv': 'import_suppliers_csv', 'suppliers': 'suppliers', 'supplier-record': 'supplier_record', 'supplier-outstanding': 'supplier_outstanding', 'supplier-ledger': 'supplier_ledger', 'merge-supplier': 'merge_supplier', 'rename-supplier': 'rename_supplier', 'supplier-changes': 'supplier_changes', 'assign-locations': 'assign_locations', 'location-inventory': 'location_inventory', 'location-changes': 'location_changes'}

def samples(name):
    return json.loads((Path(__file__).resolve().parent.parent / "examples" / name).read_text(encoding="utf-8"))

def demo(app):
    for material in samples("materials.json"):
        app.register(**material)
    for row in samples("movements.json"):
        app.movement(**row)
    return app.stock("PAPER")

def main(argv=None):
    parser = argparse.ArgumentParser(description="仓库物料台账")
    parser.add_argument("--root", required=True, help="local data directory")
    parser.add_argument("action", choices=[*ACTIONS, "demo"])
    parser.add_argument("input", nargs="?", help="UTF-8 JSON object, or array of objects, containing API arguments")
    args = parser.parse_args(argv)
    try:
        if args.action == "demo":
            # Sample operations run in a fresh child directory and never overwrite user's data.
            Path(args.root).mkdir(parents=True, exist_ok=True)
            with tempfile.TemporaryDirectory(prefix="sample-", dir=args.root) as location:
                value = demo(StockRoom(location))
        else:
            payload = json.loads(Path(args.input).read_text(encoding="utf-8")) if args.input else {}
            app = StockRoom(args.root)
            method = getattr(app, ACTIONS[args.action])
            if isinstance(payload, list):
                value = []
                for row in payload:
                    if not isinstance(row, dict):
                        raise ValueError("each input must be an object")
                    value.append(method(**row))
            elif isinstance(payload, dict):
                value = method(**payload)
            else:
                raise ValueError("input must be an object or array")
        print(json.dumps(value, ensure_ascii=False, sort_keys=True))
        return 0
    except (ValueError, KeyError, TypeError, OSError) as error:
        print(json.dumps({"error": str(error)}, ensure_ascii=False), file=sys.stderr)
        return 2

if __name__ == "__main__":
    raise SystemExit(main())
